insert into public.app_documents (key, payload) values
  ('manual', '{"title":"Becky Friends — Community Playbook","source":"MANUAL.docx","importedAt":"2026-07-31T06:00:54.759Z","blocks":[{"id":"block-001a","type":"strategy-update","html":"<article class=\"manual-chapter manual-strategy\"><header class=\"manual-chapter-hero\"><div class=\"chapter-number\">DIRECȚIE STRATEGICĂ · 04 AUGUST 2026</div><h1>Direcție strategică validată – Joacă cu sens și sistemul de experiențe Becky</h1><p class=\"manual-lead\"><strong>Statut:</strong> această secțiune fixează concluziile de direcție validate în discuția de strategie din 4 august 2026. Ea completează capitolele existente și are prioritate atunci când o formulare mai veche pare incompletă.</p><div class=\"manual-hero-mark\" aria-hidden=\"true\">✦</div></header><div class=\"manual-chapter-body manual-strategy-grid\"><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Nucleul brandului</h2><div class=\"manual-section-body\"><p><strong>Ideologia Becky:</strong> «Joacă cu sens. Conexiune autentică. Dezvoltare naturală.»</p><p><strong>Definiția de brand:</strong> Becky este locul unde familiile găsesc activități de conectare cu sine și cu cei dragi, iar joaca devine o formă de explorare și creștere personală.</p><p>Becky nu construiește doar un loc și nu oferă doar divertisment. Construiește o cultură în care familiile se întâlnesc ca să fie curioase împreună, să încerce lucruri noi, să se ajute și să crească împreună.</p><p>Formula narativă secundară este: <strong>«Copiii explorează. Părinții redescoperă. Comunitatea crește.»</strong></p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Destinația strategică și motorul ei</h2><div class=\"manual-section-body\"><p><strong>Destinația:</strong> Becky devine un hub comunitar pentru familii, unde oamenii simt că aparțin și vor să contribuie proactiv la evoluția locului.</p><p><strong>Motorul:</strong> un laborator continuu de joacă și dezvoltare proiectează, testează și rafinează activități. Evenimentele sunt una dintre aplicațiile acestui motor, nu finalitatea lui.</p><p>Acest lucru clarifică două formulări din manual: micro-experiențele sunt produsul experiențial concret, iar relațiile, apartenența și comunitatea sunt rezultatul strategic pe care îl construiesc.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Promisiunea experienței</h2><div class=\"manual-section-body\"><p>La Becky, jocurile, activitățile și evenimentele nu sunt distracție nedirecționată. Fiecare experiență trebuie să aibă sens și să creeze oportunități de conectare autentică, explorare și dezvoltare cognitivă, emoțională, socială sau fizică.</p><p>Categoria de lucru <strong>«Neurogames &amp; Activities»</strong> poate deveni un diferențiator important, cu condiția ca mesajele despre beneficii să fie clare, responsabile și fără promisiuni medicale sau afirmații neverificate. Comunicăm abilitățile exersate – atenție, memorie de lucru, coordonare, flexibilitate, autoreglare, colaborare – nu rezultate clinice garantate.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>Grădina este prima experiență Becky</h2><div class=\"manual-section-body\"><p>Grădina și zona de întâmpinare nu sunt o simplă curte sau un spațiu de așteptare. Ele sunt showroom-ul viu al viziunii Becky și un selling point major, mai ales pentru părinții care rămân aici în timpul petrecerilor.</p><p>Spațiul trebuie să spună povestea înainte ca echipa să o explice: vizitatorul observă jocuri și provocări, vede copii colaborând, citește ce abilitate exersează fiecare activitate, încearcă și el și înțelege că Becky oferă mai mult decât entertainment.</p><p>Momentul de întâmpinare nu trebuie tratat doar ca timp de umplut până se strânge grupul. Este o ocazie de conectare individuală cu fiecare familie, de orientare și de introducere blândă în cultura Becky.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Trei straturi de micro-experiențe</h2><div class=\"manual-section-body\"><p><strong>1. Self-guided:</strong> majoritatea activităților sunt intuitive și pot fi începute fără animator; ceea ce nu este evident are instrucțiuni și explicații la îndemână.</p><p><strong>2. Facilitate:</strong> un ghid, animator sau părinte adaugă profunzime, pune întrebări, adaptează regulile și susține copilul sau grupul.</p><p><strong>3. De grup și orchestrate:</strong> activități precum neurojocuri, treasure hunt, construcții colaborative, provocări, dans sau karaoke sunt combinate în experiențe comune și evenimente.</p><p>Părintele trebuie să poată alege: se implică direct alături de copil sau îl lasă ghidat de un facilitator și își ia timp pentru sine. În ambele situații, familia primește atenție și o experiență coerentă.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Adulții sunt participanți, nu însoțitori</h2><div class=\"manual-section-body\"><p>Becky este pentru întreaga familie. Adulții sunt invitați să redevină curioși și jucăuși prin puzzle-uri mecanice, ghicitori logice, provocări vizuale, construcții colaborative, jocuri conversaționale, mici experimente, jocuri rapide de masă și provocări în doi.</p><p>Experiența adultului poate avansa gradual de la activități cu expunere mică și confort ridicat către colaborare, mișcare și momente expresive precum karaoke. Scopul este ieșirea firească, nu forțată, din zona de confort și conectarea între generații.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Customer journey-ul Becky</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li><strong>Descoperă:</strong> intră, observă și devine curios; grădina începe povestea.</li><li><strong>Explorează:</strong> atinge, rezolvă, construiește și întreabă fără presiune.</li><li><strong>Se conectează:</strong> cu sine, cu copilul, cu alți părinți, cu facilitatorii și cu comunitatea.</li><li><strong>Revine:</strong> nu doar pentru o atracție fixă, ci pentru că știe că va găsi experiențe, oameni și provocări noi.</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>Ciclul de dezvoltare – laboratorul Becky</h2><div class=\"manual-section-body\"><p>Fiecare activitate urmează un ciclu documentat: <strong>idee → prototip → test în programul zilnic și în grădină → test în combinații la petreceri → observație și feedback → rafinare → integrare în evenimente → includere în biblioteca Becky.</strong></p><p>Petrecerile sunt un mediu real de testare pentru activități și tranziții. Echipa încearcă diferite combinații, observă energia grupului și păstrează doar experiențele care funcționează coerent și aduc valoare.</p><p>Fișele de neurojocuri și materialele ghidate trebuie să poată fi folosite individual sau în grup, sub îndrumarea unui părinte ori facilitator. Exemple de abilități urmărite: coordonare bilaterală, atenție, inhibiție, memorie de lucru, orientare spațială, cooperare și autoreglare.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Evenimentul orchestrează activități validate</h2><div class=\"manual-section-body\"><p>Evenimentul nu se construiește de la zero și nu este o listă de jocuri. Este o succesiune de micro-experiențe validate, așezate pe un fir narativ și legate prin tranziții exersate.</p><p>Structura de referință este: <strong>întâmpinare și explorare → conectare/ice breaker → activități în perechi → mișcare și detensionare cognitivă → neurogames și provocări → joc cooperativ cu întregul grup → reflecție → ceremonie de celebrare sau premiere.</strong></p><p>Dansul și mișcarea au un rol operațional clar: reglează energia și detensionează cognitiv atmosfera între momente solicitante. Treasure hunt și alte formate rămân activități de testat atât la petreceri, cât și în evenimente.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Filtrul deciziilor</h2><div class=\"manual-section-body\"><p>Orice investiție, joc, activitate sau eveniment este evaluat prin cinci întrebări: are sens dincolo de ocuparea timpului? invită la explorare? creează conectare? poate fi folosit independent și aprofundat prin facilitare? poate fi testat, observat și îmbunătățit?</p><p>Investițiile se fac gradual și pragmatic. Sunt preferate intervențiile accesibile care fac viziunea vizibilă și utilizabilă zilnic, apoi sunt extinse pe baza observațiilor reale.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Ce este decis și ce rămâne de validat</h2><div class=\"manual-section-body\"><p><strong>Decis:</strong> ideologia, rolul de hub comunitar, laboratorul ca motor, grădina ca primă experiență, activitățile cu sens, implicarea adulților, combinația self-guided + facilitare și evenimentele construite din activități testate.</p><p><strong>De validat:</strong> denumirea publică «Becky Lab», denumirea și arhitectura comercială «Neurogames &amp; Activities», proporția exactă dintre self-guided și facilitat, investițiile concrete, biblioteca inițială de jocuri și ordinea optimă a etapelor fiecărui format de eveniment.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>Implicații pentru restul playbook-ului</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li><strong>Misiune și comunicare:</strong> apartenența rămâne obiectivul, iar joaca cu sens devine dovada concretă a promisiunii.</li><li><strong>Spațiu:</strong> zonele nu doar găzduiesc activități, ci explică viziunea, stimulează explorarea și fac vizibile abilitățile exersate.</li><li><strong>Echipă:</strong> gazda conectează oamenii, facilitatorul aprofundează experiențele, iar echipa observă și documentează ce funcționează.</li><li><strong>Website:</strong> trebuie să comunice din primul ecran «joacă cu sens», să arate activitățile și abilitățile exersate și să explice diferența dintre programul zilnic, petreceri și evenimente.</li></ul><p><strong>Măsurare:</strong> pe lângă revenire și apartenență, urmărim utilizarea independentă, implicarea adulților, calitatea facilitării, reacția grupurilor, activitățile validate și trecerea lor în biblioteca Becky.</p></div></section></div></article>"},{"id":"block-001","type":"overview","html":"<section class=\"manual-overview\"><header class=\"manual-cover\"><div class=\"chapter-number\">DOCUMENT VIU · BECKY FRIENDS</div><h1>Community Playbook – Becky Friends</h1><p>Structură propusă pentru manualul strategic</p><div class=\"manual-cover-note\"><strong>Joacă cu sens.</strong><span>Conexiune autentică. Dezvoltare naturală.</span></div></header><div class=\"manual-overview-grid\"><article class=\"manual-overview-card\"><h2><span class=\"manual-overview-number\">00</span><span class=\"manual-overview-separator\" aria-hidden=\"true\">—</span><span>Introducere — De ce există acest document</span></h2><p>Scopul manualului și transformarea Becky dintr-un loc de joacă într-o comunitate de familii.</p></article><article class=\"manual-overview-card\"><h2><span class=\"manual-overview-number\">01</span><span class=\"manual-overview-separator\" aria-hidden=\"true\">—</span><span>O nouă perspectivă asupra unui loc de joacă</span></h2><p>De ce competiția prin reduceri, jucării și promoții este ușor de copiat și de ce comunitatea devine avantajul competitiv real.</p></article><article class=\"manual-overview-card\"><h2><span class=\"manual-overview-number\">02</span><span class=\"manual-overview-separator\" aria-hidden=\"true\">—</span><span>De la clienți la comunitate</span></h2><p>Psihologia apartenenței și transformarea unui vizitator într-un membru implicat al comunității.</p></article><article class=\"manual-overview-card\"><h2><span class=\"manual-overview-number\">03</span><span class=\"manual-overview-separator\" aria-hidden=\"true\">—</span><span>Misiunea Becky</span></h2><p>Valorile, personalitatea brandului și imaginea pe termen lung: «Locul unde ne întâlnim».</p></article><article class=\"manual-overview-card\"><h2><span class=\"manual-overview-number\">04</span><span class=\"manual-overview-separator\" aria-hidden=\"true\">—</span><span>Becky Friends</span></h2><p>Sistemul de apartenență: niveluri, badge-uri, invitații, beneficii emoționale și evoluția membrilor.</p></article><article class=\"manual-overview-card\"><h2><span class=\"manual-overview-number\">05</span><span class=\"manual-overview-separator\" aria-hidden=\"true\">—</span><span>Cultura Becky</span></h2><p>Cum sunt primite familiile noi, cum sunt încurajate conexiunile și ce comportamente definesc comunitatea.</p></article><article class=\"manual-overview-card\"><h2><span class=\"manual-overview-number\">06</span><span class=\"manual-overview-separator\" aria-hidden=\"true\">—</span><span>Ritualurile comunității</span></h2><p>Tradițiile recurente: Movie Night, Festivalul Limonadei, Talent Showcase, Board Game Night, Family of the Month și alte ritualuri.</p></article><article class=\"manual-overview-card\"><h2><span class=\"manual-overview-number\">07</span><span class=\"manual-overview-separator\" aria-hidden=\"true\">—</span><span>Memoria comunității</span></h2><p>Copacul Becky, fotografiile Polaroid, Peretele Comunității, Povestea fiecărui an și arhiva digitală.</p></article><article class=\"manual-overview-card\"><h2><span class=\"manual-overview-number\">08</span><span class=\"manual-overview-separator\" aria-hidden=\"true\">—</span><span>Spațiul fizic</span></h2><p>Amenajarea spațiului pentru conversații, colaborare și interacțiuni spontane între familii.</p></article><article class=\"manual-overview-card\"><h2><span class=\"manual-overview-number\">09</span><span class=\"manual-overview-separator\" aria-hidden=\"true\">—</span><span>Evenimentele ca instrument, nu ca scop</span></h2><p>Rolul fiecărui eveniment în construirea relațiilor și a tradițiilor, nu doar în atragerea participanților.</p></article><article class=\"manual-overview-card\"><h2><span class=\"manual-overview-number\">10</span><span class=\"manual-overview-separator\" aria-hidden=\"true\">—</span><span>Website-ul – casa comunității</span></h2><p>Rolul website-ului ca punct central pentru calendar, galerie, Becky Friends și povestea comunității.</p></article><article class=\"manual-overview-card\"><h2><span class=\"manual-overview-number\">11</span><span class=\"manual-overview-separator\" aria-hidden=\"true\">—</span><span>Planul de implementare</span></h2><p>Plan de acțiune pe 90 de zile, 6 luni și 12 luni, prioritizare și experimente.</p></article><article class=\"manual-overview-card\"><h2><span class=\"manual-overview-number\">12</span><span class=\"manual-overview-separator\" aria-hidden=\"true\">—</span><span>Cum măsurăm succesul</span></h2><p>Indicatori relevanți: revenire, recomandări, familii active, tradiții păstrate și sentimentul de apartenență.</p></article><article class=\"manual-overview-card\"><h2><span class=\"manual-overview-number\">13</span><span class=\"manual-overview-separator\" aria-hidden=\"true\">—</span><span>Viziunea pe termen lung</span></h2><p>Cum arată Becky peste cinci ani dacă strategia este implementată consecvent.</p></article><article class=\"manual-overview-card\"><h2><span class=\"manual-overview-number\">A</span><span class=\"manual-overview-separator\" aria-hidden=\"true\">—</span><span>Manifestul Becky</span></h2><p>Identitatea Becky, manifestul, viziunea și ecosistemul care le transformă în experiențe concrete.</p></article></div></section>"},{"id":"block-002","type":"chapter","html":"<article class=\"manual-chapter\"><header class=\"manual-chapter-hero\"><div class=\"chapter-number\">CAPITOLUL 01</div><h1>De ce există Becky?</h1><div class=\"manual-hero-mark\" aria-hidden=\"true\">♡</div></header><div class=\"manual-chapter-body\"><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Realitatea de astăzi</h2><div class=\"manual-section-body\"><p>Majoritatea spațiilor de joacă sunt evaluate după dimensiune, numărul de atracții sau prețul petrecerilor. Deși acestea sunt importante, ele nu răspund unei nevoi mai profunde: dorința familiilor de a găsi un loc în care copiii și părinții să construiască relații autentice.</p><p>În multe cazuri, vizita începe și se termină în aceeași zi. Experiența este consumată, dar nu continuă.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Problema pe care o rezolvă Becky</h2><div class=\"manual-section-body\"><p>Părinții caută mai mult decât un loc sigur în care copiii să se joace. Ei caută contexte în care copiii își fac prieteni, iar ei întâlnesc familii cu valori similare.</p><p>Becky își propune să transforme un spațiu de joacă într-un punct de întâlnire al comunității.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>O schimbare de perspectivă</h2><div class=\"manual-section-body\"><p>Întrebarea nu este:</p><ul class=\"manual-list\"><li>«Cum aducem mai mulți oameni?»</li><li>Întrebarea devine:</li><li>«Cum construim un loc în care oamenii își doresc să revină împreună?»</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>Ce este Becky?</h2><div class=\"manual-section-body\"><p>Becky este un spațiu pentru joacă, dar și un loc în care iau naștere prietenii, tradiții și amintiri. Evenimentele, website-ul, Becky Friends și ritualurile există pentru a susține această misiune.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Principiile fundamentale</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>Relațiile sunt mai importante decât tranzacțiile.</li><li>Apartenența valorează mai mult decât reducerile.</li><li>Tradițiile construiesc cultura.</li><li>Comunitatea este cel mai valoros activ Becky.</li><li>Fiecare familie trebuie să se simtă binevenită.</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Cum arată succesul</h2><div class=\"manual-section-body\"><p>Succesul nu înseamnă doar un calendar plin de rezervări. Succesul înseamnă că familiile aleg Becky pentru oamenii pe care îi întâlnesc aici și spun firesc:</p><blockquote class=\"manual-quote\">«Ne vedem la Becky.»</blockquote></div></section><section class=\"manual-conclusion\"><h2><span aria-hidden=\"true\">◌</span>Concluzie</h2><div class=\"manual-section-body\"><p>Acest playbook pornește de la convingerea că un loc de joacă poate avea un impact mult mai mare decât divertismentul de câteva ore. Becky își propune să construiască o comunitate care crește odată cu familiile sale.</p></div></section><section class=\"manual-takeaways\"><h2><span aria-hidden=\"true\">→</span>Idei-cheie</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>Becky există pentru a construi comunitate, nu doar pentru a oferi joacă.</li><li>Relațiile sunt produsul real.</li><li>Apartenența este avantajul competitiv.</li><li>Fiecare experiență trebuie să apropie oamenii.</li><li>Obiectivul final: «Ne vedem la Becky.»</li></ul></div></section></div></article>"},{"id":"block-003","type":"chapter","html":"<article class=\"manual-chapter\"><header class=\"manual-chapter-hero\"><div class=\"chapter-number\">CAPITOLUL 02</div><h1>De la clienți la comunitate</h1><div class=\"manual-hero-mark\" aria-hidden=\"true\">✦</div></header><div class=\"manual-chapter-body\"><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Schimbarea de perspectivă</h2><div class=\"manual-section-body\"><p>Majoritatea spațiilor de joacă încearcă să atragă cât mai mulți clienți prin reduceri, promoții, facilități noi sau petreceri. Aceste elemente sunt importante, dar au un dezavantaj major: pot fi copiate foarte ușor.</p><p>Comunitatea este diferită. Ea nu poate fi cumpărată și nu poate fi replicată peste noapte. Se construiește prin experiențe repetate, relații și încredere. Obiectivul Becky nu este doar să umple locația, ci să creeze un loc în care familiile aleg să revină pentru oamenii pe care îi întâlnesc și pentru atmosfera pe care o simt.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Diferența dintre client și membru</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>Un client cumpără un serviciu. Un membru aparține unui grup.</li><li>Clientul întreabă „Ce primesc astăzi?” Membrul întreabă „Când ne întâlnim din nou?”</li><li>Clientul compară prețuri. Membrul compară experiențele și relațiile create.</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Piramida apartenenței</h2><div class=\"manual-section-body\"><div class=\"manual-flowline\">Vizitator → Vizitator recurent → Prieten Becky → De-al Casei → Sufletul Comunității.</div><p>Fiecare treaptă este câștigată prin implicare: participare la evenimente, invitații către alte familii, contribuții cu idei și sprijin pentru membrii noi.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>Psihologia apartenenței</h2><div class=\"manual-section-body\"><p>Părinții caută locuri în care copiii își fac prieteni, iar ei întâlnesc familii cu valori similare. Când Becky devine acel loc, alegerea nu mai este dictată doar de preț sau distanță, ci de sentimentul că acolo aparțin.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Relațiile sunt produsul</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>Board Game Night creează conversații. Movie Night creează amintiri.</li><li>Festivalul Limonadei creează colaborare. Talent Showcase creează curaj și încurajare.</li><li>Evenimentele sunt instrumente. Produsul real este relația dintre familii.</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Cum se construiește comunitatea</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>Organizăm evenimente care facilitează interacțiunea.</li><li>Introducem ritualuri recurente (Familia Lunii, badge-uri, Copacul Becky, Cutia cu idei).</li><li>Oferim oportunități de implicare membrilor.</li><li>Încurajăm invitațiile între familii.</li><li>Lăsăm comunitatea să înceapă să se auto-organizeze.</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Exemple</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>Două familii se cunosc la Board Game Night și continuă să vină împreună.</li><li>O familie nouă este întâmpinată de o familie „De-al Casei”.</li><li>Copiii își caută fotografiile Polaroid din Copacul Becky și își doresc să participe din nou.</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>Indicatorul suprem al succesului</h2><div class=\"manual-section-body\"><p>Succesul nu este doar un număr mare de participanți. Succesul este momentul în care oamenii își dau întâlnire la Becky fără ca echipa să organizeze un eveniment special.</p></div></section><section class=\"manual-takeaways\"><h2><span aria-hidden=\"true\">✦</span>Ideile-cheie</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>Evenimentele sunt pretextul; relațiile sunt rezultatul.</li><li>Apartenența valorează mai mult decât reducerile.</li><li>Ritualurile creează cultură.</li><li>Comunitatea este cel mai greu avantaj competitiv de copiat.</li><li>Obiectivul final: «Ne vedem la Becky.»</li></ul></div></section></div></article>"},{"id":"block-004","type":"chapter","html":"<article class=\"manual-chapter\"><header class=\"manual-chapter-hero\"><div class=\"chapter-number\">CAPITOLUL 03</div><h1>Misiunea Becky</h1><div class=\"manual-hero-mark\" aria-hidden=\"true\">♡</div></header><div class=\"manual-chapter-body\"><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>De ce există Becky</h2><div class=\"manual-section-body\"><p>Un loc de joacă poate oferi tobogane, jucării și petreceri. Becky își propune să ofere ceva mai greu de construit: un loc în care familiile simt că aparțin.</p><p>Misiunea nu este să organizeze activități. Misiunea este să creeze contexte în care apar relații autentice între copii și între părinți.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Misiunea</h2><div class=\"manual-section-body\"><p>Becky există pentru a crea un spațiu în care familiile petrec timp de calitate împreună, își construiesc prietenii și dezvoltă o comunitate bazată pe încredere, joacă și implicare.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Viziunea</h2><div class=\"manual-section-body\"><p>Peste câțiva ani, Becky nu ar trebui să fie cunoscut drept «un loc de joacă foarte frumos», ci drept locul unde familiile din Constanța își dau întâlnire în mod firesc.</p><p>Scopul este ca expresia «Ne vedem la Becky» să devină un obicei.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>Valorile comunității</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>Apartenență înainte de tranzacție.</li><li>Oameni înainte de facilități.</li><li>Participare înainte de consum.</li><li>Bunătate și respect.</li><li>Curiozitate și creativitate.</li><li>Contribuție la binele comunității.</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Personalitatea brandului</h2><div class=\"manual-section-body\"><p>Becky este caldă, primitoare, autentică și optimistă. Nu comunică agresiv și nu pune presiune pe vânzare. Invită oamenii să facă parte dintr-o poveste comună.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Cum comunicăm</h2><div class=\"manual-section-body\"><p>În loc de «Vă invităm la eveniment», folosim «Ne întâlnim pe...». În loc de «Clienții noștri», folosim «Familiile Becky».</p><p>În loc de «Promoție», punem accent pe experiență, tradiție și comunitate.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Promisiunea Becky</h2><div class=\"manual-section-body\"><p>Orice familie care trece pragul Becky trebuie să plece cu sentimentul că a fost bine primită și că va fi recunoscută la următoarea vizită. Această continuitate creează încredere și loialitate.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>Cum se reflectă misiunea în deciziile zilnice</h2><div class=\"manual-section-body\"><p>Fiecare activitate, fiecare tradiție și fiecare investiție trebuie evaluată printr-o întrebare simplă:</p><p>«Ajută această idee oamenii să se cunoască, să participe și să simtă că aparțin?» Dacă răspunsul este da, ideea este aliniată cu misiunea Becky.</p></div></section><section class=\"manual-conclusion\"><h2><span aria-hidden=\"true\">✦</span>Concluzie</h2><div class=\"manual-section-body\"><p>Misiunea Becky nu este organizarea celor mai multe evenimente și nici oferirea celor mai multe beneficii. Misiunea este construirea unui loc în care copiii și părinții își creează amintiri și relații care îi fac să revină iar și iar.</p></div></section></div></article>"},{"id":"block-005","type":"chapter","html":"<article class=\"manual-chapter\"><header class=\"manual-chapter-hero\"><div class=\"chapter-number\">CAPITOLUL 04</div><h1>Becky Friends</h1><div class=\"manual-hero-mark\" aria-hidden=\"true\">✦</div></header><div class=\"manual-chapter-body\"><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Ce este Becky Friends?</h2><div class=\"manual-section-body\"><p>Becky Friends nu este un program de fidelizare bazat pe reduceri. Este un sistem de apartenență care transformă vizitatorii în membri activi ai comunității. Scopul său este să creeze sentimentul că fiecare familie face parte din povestea Becky.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>De ce un sistem de apartenență?</h2><div class=\"manual-section-body\"><p>Reducerile pot aduce o vizită în plus. Apartenența aduce ani de relație. Atunci când oamenii simt că locul îi cunoaște și îi apreciază, motivația de a reveni devine emoțională, nu financiară.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Nivelurile Becky Friends</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>Invitat – prima experiență Becky.</li><li>Prieten Becky – începe să participe regulat și cunoaște alte familii.</li><li>De-al Casei – este recunoscut de comunitate, revine frecvent și contribuie la atmosfera locului.</li><li>Sufletul Comunității (denumire provizorie) – modelează cultura Becky, îi întâmpină pe cei noi și inspiră implicarea.</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>Cum evoluează o familie?</h2><div class=\"manual-section-body\"><p>Progresul se bazează pe implicare, nu pe bani cheltuiți. Exemple:</p><ul class=\"manual-list\"><li>participarea la evenimente;</li><li>aducerea unei alte familii în comunitate;</li><li>contribuții prin idei;</li><li>participarea la tradiții;</li><li>implicarea în viața comunității.</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Badge-uri</h2><div class=\"manual-section-body\"><p>Fiecare experiență importantă poate oferi un badge simbolic. Exemple:</p><ul class=\"manual-list\"><li>Board Game Explorer</li><li>Movie Night</li><li>Lemonade Creator</li><li>Talent Showcase</li><li>LEGO Builder</li><li>Science Explorer</li><li>Badge-urile spun povestea participării unei familii și încurajează revenirea.</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Invită un prieten</h2><div class=\"manual-section-body\"><p>În locul unui program clasic «Recomandă și primești reducere», Becky Friends recompensează experiența comună. Când o familie invită o altă familie care devine membră, ambele primesc acces la o experiență specială sau un badge dedicat. Accentul cade pe construirea comunității.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Recunoașterea membrilor</h2><div class=\"manual-section-body\"><p>Familiile implicate sunt celebrate prin:</p><ul class=\"manual-list\"><li>Familia Lunii;</li><li>apariția pe Peretele Comunității;</li><li>fotografii Polaroid în Copacul Becky;</li><li>roluri simbolice la anumite evenimente;</li><li>acces la întâlniri dedicate membrilor.</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>Principii de design</h2><div class=\"manual-section-body\"><p>Programul trebuie să fie simplu, cald și ușor de înțeles. Limbajul folosit vorbește despre prietenie și apartenență, nu despre puncte, reduceri sau recompense financiare.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Rezultatul dorit</h2><div class=\"manual-section-body\"><p>Succesul Becky Friends este atins atunci când membrii spun firesc:</p><blockquote class=\"manual-quote\">«Hai să îi chemăm și pe prietenii noștri.»</blockquote><p>În acel moment, comunitatea începe să crească organic.</p></div></section><section class=\"manual-takeaways\"><h2><span aria-hidden=\"true\">♡</span>Idei-cheie</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>Fidelizarea se bazează pe apartenență, nu pe reduceri.</li><li>Badge-urile spun povestea implicării.</li><li>Invitarea altor familii dezvoltă comunitatea.</li><li>Statutul se câștigă prin contribuție.</li><li>Becky Friends este identitatea comunității.</li></ul></div></section></div></article>"},{"id":"block-006","type":"chapter","html":"<article class=\"manual-chapter\"><header class=\"manual-chapter-hero\"><div class=\"chapter-number\">CAPITOLUL 05</div><h1>Cultura Becky</h1><div class=\"manual-hero-mark\" aria-hidden=\"true\">♡</div></header><div class=\"manual-chapter-body\"><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Ce înseamnă cultura Becky?</h2><div class=\"manual-section-body\"><p>Cultura Becky reprezintă suma comportamentelor, tradițiilor și valorilor care îi fac pe oameni să spună: «Aici mă simt bine». Ea nu este creată de un regulament, ci de felul în care familiile interacționează și de atmosfera pe care o întâlnesc la fiecare vizită.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Cultura este avantajul competitiv</h2><div class=\"manual-section-body\"><p>Un loc de joacă poate fi copiat. O comunitate cu o cultură autentică nu poate. Cultura apare atunci când oamenii încep să transmită mai departe felul în care se simt la Becky și îi invită pe alții să facă parte din aceeași experiență.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Valorile trăite zilnic</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>Primim cu căldură fiecare familie nouă.</li><li>Încurajăm copiii să se joace împreună, nu separat.</li><li>Părinții sunt invitați să socializeze, nu doar să aștepte.</li><li>Fiecare familie poate contribui cu idei și inițiative.</li><li>Respectul, bunătatea și implicarea sunt mai importante decât competiția.</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>Limbajul comunității</h2><div class=\"manual-section-body\"><p>Comunicarea reflectă cultura. În loc de «Vă invităm la eveniment», folosim «Ne întâlnim pe...». În loc de «clienți», vorbim despre «familiile Becky». Tonul este cald, personal și orientat spre apartenență.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Ritualuri mici, efect mare</h2><div class=\"manual-section-body\"><p>Cultura se construiește prin gesturi repetate:</p><ul class=\"manual-list\"><li>salutarea familiilor pe nume;</li><li>prezentarea familiilor noi altor membri;</li><li>fotografii Polaroid după anumite momente;</li><li>badge-uri pentru implicare;</li><li>Familia Lunii;</li><li>Cutia cu idei.</li><li>Aceste ritualuri creează continuitate și identitate.</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Tradițiile Becky</h2><div class=\"manual-section-body\"><p>Evenimentele recurente devin tradiții: Board Game Night, Movie Night, Festivalul Limonadei, Talent Showcase, Dress Theme Party, Schimb de jucării. Oamenii nu participă doar la un eveniment, ci la o tradiție a comunității.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Contribuția comunității</h2><div class=\"manual-section-body\"><p>Familiile nu sunt doar participante. Ele lasă ceva în urmă: o fotografie, o idee, o piesă LEGO, o pictură comună sau un mesaj. Astfel, fiecare eveniment contribuie la povestea Becky.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>Rolul membrilor implicați</h2><div class=\"manual-section-body\"><p>Familiile «De-al Casei» și «Sufletele Comunității» devin exemple pentru ceilalți. Pot întâmpina familii noi, pot deschide simbolic anumite evenimente și pot inspira implicarea fără a avea roluri formale de organizatori.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Cum știm că cultura funcționează?</h2><div class=\"manual-section-body\"><p>Semnele sunt simple:</p><ul class=\"manual-list\"><li>oamenii își dau întâlnire la Becky;</li><li>familiile se cunosc între ele;</li><li>copiii își caută prietenii la intrare;</li><li>părinții rămân la povești și după terminarea activităților;</li><li>comunitatea generează singură idei și inițiative.</li></ul></div></section><section class=\"manual-conclusion\"><h2><span aria-hidden=\"true\">♡</span>Concluzie</h2><div class=\"manual-section-body\"><p>Cultura Becky nu este un proiect cu început și sfârșit. Este un mod de a lua decizii și de a construi relații. Dacă fiecare acțiune întărește sentimentul de apartenență, Becky va deveni un reper al comunității, nu doar un loc de joacă.</p></div></section><section class=\"manual-takeaways\"><h2><span aria-hidden=\"true\">◌</span>Idei-cheie</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>Cultura se construiește prin gesturi mici repetate.</li><li>Tradițiile sunt mai puternice decât campaniile.</li><li>Fiecare familie poate contribui la povestea Becky.</li><li>Comunitatea trebuie să poată funcționa și fără evenimente organizate permanent.</li><li>Scopul final este un loc în care oamenii simt că aparțin.</li></ul></div></section></div></article>"},{"id":"block-007","type":"chapter","html":"<article class=\"manual-chapter\"><header class=\"manual-chapter-hero\"><div class=\"chapter-number\">CAPITOLUL 06</div><h1>Ritualurile comunității</h1><div class=\"manual-hero-mark\" aria-hidden=\"true\">✦</div></header><div class=\"manual-chapter-body\"><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>De ce contează ritualurile?</h2><div class=\"manual-section-body\"><p>Evenimentele pot fi uitate. Ritualurile rămân. Un ritual este o experiență repetată care îi face pe oameni să simtă că fac parte din aceeași poveste. Ele oferă comunității identitate și creează amintiri pe termen lung.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Diferența dintre un eveniment și un ritual</h2><div class=\"manual-section-body\"><p>Un eveniment este organizat într-o anumită zi. Un ritual se repetă și devine așteptat. Oamenii nu spun doar «Am fost la Movie Night», ci «În fiecare lună mergem la Movie Night de la Becky». Acesta este momentul în care experiența devine tradiție.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Ritualurile recurente Becky</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>Board Game Night</li><li>Movie Night / Pijamale S Popcorn</li><li>Festivalul Limonadei</li><li>Talent Showcase</li><li>Dress Theme Party</li><li>LEGO Day</li><li>Science Day</li><li>Schimb de jucării</li><li>Schimb de cărți și jocuri</li><li>Coffee S Play Morning</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>Tradiții care construiesc apartenența</h2><div class=\"manual-section-body\"><p>La fiecare eveniment trebuie să existe un element care se repetă: aceeași fotografie de grup, aceeași melodie de început, același mod de premiere sau același salut. Repetiția transformă experiențele în identitatea comunității.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Familia Lunii</h2><div class=\"manual-section-body\"><p>În fiecare lună este recunoscută o familie implicată în comunitate. Criteriul nu este performanța, ci contribuția: implicare, bunătate, ajutor oferit altor familii sau participare constantă.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Copacul Becky</h2><div class=\"manual-section-body\"><p>La anumite evenimente se realizează fotografii instant (Polaroid). Familiile scriu un mesaj pe spatele fotografiei și o adaugă în Copacul Becky sau pe Peretele Comunității. La finalul anului se creează o poveste vizuală a tuturor momentelor importante.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Ritualuri spontane</h2><div class=\"manual-section-body\"><p>Nu toate ritualurile trebuie organizate de echipă. Raftul cu board games, masa comunității sau panoul «Cine mai intră într-un joc?» încurajează interacțiuni spontane între familii.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>Calendarul comunității</h2><div class=\"manual-section-body\"><p>Comunitatea trebuie să știe că anumite ritualuri au loc în fiecare lună. În loc de «Vă invităm la...», comunicarea poate spune: «Ne întâlnim pe...». Astfel, participarea devine un obicei.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Cum apar tradițiile noi</h2><div class=\"manual-section-body\"><p>Becky trebuie să lase loc ideilor venite din comunitate. Cutia cu idei și votul membrilor Becky Friends pot transforma propunerile familiilor în noi ritualuri anuale.</p></div></section><section class=\"manual-conclusion\"><h2><span aria-hidden=\"true\">♡</span>Concluzie</h2><div class=\"manual-section-body\"><p>Ritualurile sunt mecanismul prin care cultura Becky se transmite din generație în generație de membri. Ele transformă un loc de joacă într-un reper al comunității.</p></div></section><section class=\"manual-takeaways\"><h2><span aria-hidden=\"true\">◌</span>Idei-cheie</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>Ritualurile creează identitate.</li><li>Repetiția generează apartenență.</li><li>Tradițiile sunt mai valoroase decât campaniile.</li><li>Comunitatea contribuie la apariția unor ritualuri noi.</li><li>Fiecare an trebuie să lase o poveste vizibilă în Becky.</li></ul></div></section></div></article>"},{"id":"block-008","type":"chapter","html":"<article class=\"manual-chapter\"><header class=\"manual-chapter-hero\"><div class=\"chapter-number\">CAPITOLUL 07</div><h1>Memoria comunității</h1><div class=\"manual-hero-mark\" aria-hidden=\"true\">♡</div></header><div class=\"manual-chapter-body\"><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>De ce este importantă memoria unei comunități?</h2><div class=\"manual-section-body\"><p>O comunitate nu este definită doar de oamenii care o formează astăzi, ci și de amintirile pe care le construiește în timp. Memoria comunității oferă continuitate și transformă fiecare vizită într-o parte dintr-o poveste mai mare.</p><p>Familiile nu își vor aminti toate jocurile sau toate activitățile, dar își vor aminti oamenii, emoțiile și momentele speciale trăite împreună.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Becky ca loc al amintirilor</h2><div class=\"manual-section-body\"><p>Becky își propune să fie locul unde copiii cresc împreună și unde părinții își creează prietenii. De aceea, fiecare experiență importantă trebuie să lase o urmă vizibilă în spațiul comunității.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Copacul Becky</h2><div class=\"manual-section-body\"><p>Copacul Becky este simbolul memoriei colective. La anumite evenimente, familiile primesc o fotografie instant (Polaroid), scriu un mesaj pe verso și o agață în Copacul Becky sau pe Peretele Comunității.</p><p>În timp, copacul devine jurnalul vizual al tuturor momentelor importante.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>Peretele Comunității</h2><div class=\"manual-section-body\"><p>Peretele Comunității prezintă familiile implicate, fotografii din evenimente, badge-uri speciale și momente memorabile. Nu este un panou de promovare, ci o arhivă vie care arată evoluția comunității.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Povestea fiecărui an</h2><div class=\"manual-section-body\"><p>La finalul fiecărui an, comunitatea poate privi în urmă și vedea cum a crescut. Fotografiile, mesajele și tradițiile creează un album colectiv care devine tot mai valoros cu fiecare generație de familii.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Rolul copiilor</h2><div class=\"manual-section-body\"><p>Copiii își caută fotografiile, își recitesc mesajele și își amintesc evenimentele la care au participat. Aceste mici ritualuri întăresc atașamentul emoțional față de Becky.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Rolul părinților</h2><div class=\"manual-section-body\"><p>Părinții retrăiesc momentele petrecute împreună și văd cum copiii lor cresc în cadrul aceleiași comunități. Becky devine astfel un reper al unei etape importante din viața familiei.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>Memoria digitală</h2><div class=\"manual-section-body\"><p>Website-ul Becky completează memoria fizică prin galerii foto, povești, calendarul evenimentelor și arhiva comunității. Astfel, fiecare familie poate retrăi experiențele și le poate împărtăși mai departe.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Moștenirea comunității</h2><div class=\"manual-section-body\"><p>Cea mai mare realizare nu este numărul de evenimente organizate, ci faptul că peste ani oamenii vor spune: «Îți amintești când mergeam la Becky?». În acel moment, comunitatea a devenit parte din identitatea lor.</p></div></section><section class=\"manual-conclusion\"><h2><span aria-hidden=\"true\">♡</span>Concluzie</h2><div class=\"manual-section-body\"><p>Memoria comunității transformă experiențele de moment în amintiri care durează o viață. Ea este dovada că Becky nu oferă doar joacă, ci construiește povești și relații care rămân în sufletul familiilor.</p></div></section><section class=\"manual-takeaways\"><h2><span aria-hidden=\"true\">◌</span>Idei-cheie</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>Fiecare eveniment ar trebui să lase o amintire vizibilă.</li><li>Copacul Becky și Peretele Comunității spun povestea locului.</li><li>Memoria consolidează sentimentul de apartenență.</li><li>Fotografiile și mesajele au valoare emoțională pe termen lung.</li><li>O comunitate puternică își păstrează și își transmite propria poveste.</li></ul></div></section></div></article>"},{"id":"block-009","type":"chapter","html":"<article class=\"manual-chapter\"><header class=\"manual-chapter-hero\"><div class=\"chapter-number\">CAPITOLUL 08</div><h1>Spațiul care construiește comunitatea</h1><div class=\"manual-hero-mark\" aria-hidden=\"true\">✦</div></header><div class=\"manual-chapter-body\"><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Spațiul este un facilitator</h2><div class=\"manual-section-body\"><p>Un spațiu bine proiectat nu este doar frumos, ci îi încurajează pe oameni să interacționeze. Modul în care sunt așezate mesele, zonele de joacă și locurile de relaxare influențează direct conversațiile și relațiile care se formează.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Zone cu scop clar</h2><div class=\"manual-section-body\"><p>Becky poate fi organizată în zone complementare: joacă liberă, activități creative, aniversări, relaxare pentru părinți și un punct dedicat comunității. Fiecare zonă trebuie să invite la participare, nu doar la consum.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Colțul comunității</h2><div class=\"manual-section-body\"><p>Un spațiu vizibil găzduiește calendarul, Copacul Becky, Peretele Comunității, badge-urile și fotografiile. Acesta amintește permanent că Becky este mai mult decât un loc de joacă.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>Masa comunității</h2><div class=\"manual-section-body\"><p>O masă comună pentru cafea, board games sau discuții reduce barierele dintre familii și facilitează conversațiile spontane.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Elemente care spun o poveste</h2><div class=\"manual-section-body\"><p>Fotografiile, mesajele copiilor, ilustrațiile și obiectele create în cadrul atelierelor personalizează spațiul și îl fac să reflecte comunitatea, nu doar designul interior.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Flexibilitate</h2><div class=\"manual-section-body\"><p>Mobilierul și amenajarea ar trebui să permită transformarea rapidă a spațiului pentru Movie Night, LEGO Day, ateliere, spectacole sau întâlniri ale comunității.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Experiența de la intrare la ieșire</h2><div class=\"manual-section-body\"><p>Fiecare vizită începe cu un salut și se încheie cu sentimentul că familia este așteptată să revină. Micile detalii – întâmpinarea, semnalistica și despărțirea – contribuie la această experiență.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>Spațiul digital</h2><div class=\"manual-section-body\"><p>Website-ul și canalele sociale completează spațiul fizic. Calendarul, galeriile foto și poveștile comunității prelungesc experiența Becky și între vizite.</p></div></section><section class=\"manual-conclusion\"><h2><span aria-hidden=\"true\">✦</span>Concluzie</h2><div class=\"manual-section-body\"><p>Spațiul Becky nu este doar decorul activităților. El este un instrument care susține relațiile, tradițiile și cultura comunității.</p></div></section><section class=\"manual-takeaways\"><h2><span aria-hidden=\"true\">♡</span>Idei-cheie</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>Fiecare zonă trebuie să încurajeze interacțiunea.</li><li>Elementele comunității trebuie să fie vizibile.</li><li>Spațiul trebuie să fie flexibil pentru ritualuri și evenimente.</li><li>Experiența contează din momentul intrării până la plecare.</li><li>Designul susține cultura, nu o înlocuiește.</li></ul></div></section></div></article>"},{"id":"block-010","type":"chapter","html":"<article class=\"manual-chapter\"><header class=\"manual-chapter-hero\"><div class=\"chapter-number\">CAPITOLUL 09</div><h1>Evenimentele ca instrumente de construire a comunității</h1><div class=\"manual-hero-mark\" aria-hidden=\"true\">♡</div></header><div class=\"manual-chapter-body\"><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Evenimentele nu sunt scopul</h2><div class=\"manual-section-body\"><p>Evenimentele nu reprezintă produsul principal Becky, ci mecanismul prin care oamenii se cunosc, interacționează și își creează amintiri. Valoarea lor se măsoară prin relațiile pe care le generează, nu doar prin numărul de participanți.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Fiecare eveniment are un obiectiv</h2><div class=\"manual-section-body\"><p>Înainte de organizare, echipa își pune întrebarea: «Ce relații vrem să apară?». Unele evenimente încurajează colaborarea între copii, altele conversațiile dintre părinți sau integrarea familiilor noi.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Portofoliul Becky</h2><div class=\"manual-section-body\"><p>Evenimentele recurente pot include:</p><ul class=\"manual-list\"><li>Board Game Night</li><li>Movie Night</li><li>Festivalul Limonadei</li><li>LEGO Day</li><li>Science Day</li><li>Talent Showcase</li><li>Coffee S Play Morning</li><li>Schimb de jucării și cărți.</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>Experiențe, nu spectacole</h2><div class=\"manual-section-body\"><p>Participanții nu sunt spectatori. Ei sunt implicați activ prin jocuri, provocări, activități creative și momente în care colaborează între ei.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Integrarea familiilor noi</h2><div class=\"manual-section-body\"><p>Fiecare eveniment trebuie să ofere ocazii prin care familiile noi să fie prezentate membrilor Becky Friends și să intre ușor în conversații și activități.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Continuitatea</h2><div class=\"manual-section-body\"><p>Evenimentele nu sunt experiențe izolate. Ele fac parte dintr-un calendar anual și dintr-o poveste comună, fiecare contribuind la cultura Becky.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Cum măsurăm succesul</h2><div class=\"manual-section-body\"><p>Pe lângă participare, sunt urmărite:</p><ul class=\"manual-list\"><li>câte familii revin;</li><li>câte familii se cunosc între ele;</li><li>câte invitații sunt făcute;</li><li>câte amintiri și fotografii sunt create;</li><li>cât de des oamenii spun «Ne vedem la Becky».</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>După eveniment</h2><div class=\"manual-section-body\"><p>Experiența continuă prin fotografii, povești, mulțumiri, badge-uri și arhivarea momentelor în memoria comunității și pe website.</p></div></section><section class=\"manual-conclusion\"><h2><span aria-hidden=\"true\">✦</span>Concluzie</h2><div class=\"manual-section-body\"><p>Un eveniment reușit nu este cel care umple spațiul pentru o zi, ci cel care determină familiile să își dorească să revină împreună și să aducă alți oameni în comunitate.</p></div></section><section class=\"manual-takeaways\"><h2><span aria-hidden=\"true\">♡</span>Idei-cheie</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>Evenimentele sunt un mijloc, nu scopul.</li><li>Participarea este mai importantă decât spectacolul.</li><li>Fiecare eveniment trebuie să întărească relațiile.</li><li>Calendarul creează continuitate.</li><li>Succesul se măsoară prin comunitatea construită.</li></ul></div></section></div></article>"},{"id":"block-011","type":"chapter","html":"<section class=\"chapter\">\n\n    <div class=\"hero\">\n\n        <div class=\"chapter-number\">\n            CAPITOLUL 10\n        </div>\n\n        <h1>Website-ul și ecosistemul digital Becky</h1>\n\n        <p>\n            Website-ul Becky nu este doar un website. Este\n            <strong>casa digitală a comunității</strong>,\n            locul unde familiile descoperă, retrăiesc și continuă\n            experiența Becky dintre două vizite.\n        </p>\n\n    </div>\n\n    <div class=\"section\">\n\n        <h2>Privire de ansamblu</h2>\n\n        <div class=\"summary-grid\">\n\n            <div class=\"summary-card\">\n                <h3>🏠 Casa comunității</h3>\n                Website-ul devine punctul central unde toate experiențele Becky se întâlnesc.\n            </div>\n\n            <div class=\"summary-card\">\n                <h3>📅 Mereu se întâmplă ceva</h3>\n                Calendarul transmite că există permanent activități și motive de revenire.\n            </div>\n\n            <div class=\"summary-card\">\n                <h3>📸 Memoria comunității</h3>\n                Fiecare eveniment rămâne într-o arhivă de fotografii și povești.\n            </div>\n\n            <div class=\"summary-card\">\n                <h3>⭐ Apartenență</h3>\n                Becky''s Friends oferă continuitate și sentimentul că faci parte din comunitate.\n            </div>\n\n        </div>\n\n    </div>\n\n    <div class=\"section\">\n\n        <h2>Cum ajung familiile aici</h2>\n\n        <div class=\"flow\">\n\n            <div class=\"flow-step\">\n                <strong>Social Media</strong>\n                Atrage atenția\n            </div>\n\n            <div class=\"arrow\">→</div>\n\n            <div class=\"flow-step\">\n                <strong>Website</strong>\n                Inspiră și informează\n            </div>\n\n            <div class=\"arrow\">→</div>\n\n            <div class=\"flow-step\">\n                <strong>Experiența Becky</strong>\n                Petreceri și evenimente\n            </div>\n\n            <div class=\"arrow\">→</div>\n\n            <div class=\"flow-step\">\n                <strong>Comunitatea</strong>\n                Revine și recomandă\n            </div>\n\n        </div>\n\n    </div>\n\n    <div class=\"section\">\n\n        <h2>Structura website-ului</h2>\n\n        <div class=\"website-grid\">\n\n            <div class=\"website-card\">\n                <h3>🏠 Privire de ansamblu</h3>\n                <p>Prima impresie despre universul Becky și acces rapid către cele mai importante experiențe.</p>\n            </div>\n\n            <div class=\"website-card\">\n                <h3>🎂 Petreceri de copii</h3>\n                <p>Informații despre aniversări, rezervări și experiențele dedicate familiilor.</p>\n            </div>\n\n            <div class=\"website-card\">\n                <h3>🎉 Evenimente Becky</h3>\n                <p>Calendarul complet al comunității și toate activitățile planificate.</p>\n            </div>\n\n            <div class=\"website-card\">\n                <h3>👨‍👩‍👧 Să ne cunoaștem</h3>\n                <p>Povestea Becky, valorile și oamenii care construiesc comunitatea.</p>\n            </div>\n\n            <div class=\"website-card\">\n                <h3>📸 Poze și amintiri</h3>\n                <p>Galerii foto și momente care păstrează vie memoria comunității.</p>\n            </div>\n\n            <div class=\"website-card\">\n                <h3>⭐ Becky''s Friends</h3>\n                <p>Niveluri de apartenență, participări și recunoașterea familiilor implicate.</p>\n            </div>\n\n        </div>\n\n    </div>\n\n    <div class=\"cta\">\n\n        <h2>Construim împreună comunitatea Becky?</h2>\n\n        <p>\n            Website-ul devine locul în care fiecare familie poate reveni,\n            indiferent dacă participă la un eveniment, organizează o petrecere\n            sau își retrăiește amintirile.\n        </p>\n\n        <div class=\"cta-btn\">\n            Contactează-ne\n        </div>\n\n    </div>\n\n    <div class=\"section\">\n\n        <h2>Cum măsurăm succesul</h2>\n\n        <div class=\"kpi-grid\">\n\n            <div class=\"kpi\">\n                <small>număr de</small>\n                <strong>EVENIMENTE</strong>\n                <p>organizate anual</p>\n            </div>\n\n            <div class=\"kpi\">\n                <small>număr de</small>\n                <strong>PETRECERI</strong>\n                <p>organizate pentru familii</p>\n            </div>\n\n            <div class=\"kpi\">\n                <small>număr de</small>\n                <strong>TESTIMONIALE</strong>\n                <p>primite din partea comunității</p>\n            </div>\n\n            <div class=\"kpi\">\n                <small>număr de</small>\n                <strong>BECKY''S FRIENDS</strong>\n                <p>familii care revin constant</p>\n            </div>\n\n        </div>\n\n    </div>\n\n    <div class=\"section\">\n\n        <h2>Ideile esențiale</h2>\n\n        <div class=\"takeaways\">\n\n            <div class=\"takeaway\">\n                <div class=\"icon\">✔</div>\n                <div>Website-ul este casa digitală a comunității Becky.</div>\n            </div>\n\n            <div class=\"takeaway\">\n                <div class=\"icon\">✔</div>\n                <div>Social media atrage atenția, website-ul construiește relația.</div>\n            </div>\n\n            <div class=\"takeaway\">\n                <div class=\"icon\">✔</div>\n                <div>Calendarul și galeriile mențin comunitatea activă între vizite.</div>\n            </div>\n\n            <div class=\"takeaway\">\n                <div class=\"icon\">✔</div>\n                <div>Conținutul pune accent pe oameni și pe experiențele lor.</div>\n            </div>\n\n            <div class=\"takeaway\">\n                <div class=\"icon\">✔</div>\n                <div>Becky''s Friends transformă vizitele ocazionale într-o comunitate recurentă.</div>\n            </div>\n\n        </div>\n\n    </div>\n\n</section>"},{"id":"block-012","type":"chapter","html":"<section class=\"chapter\">\n\n<div class=\"hero\">\n\n<div class=\"chapter-number\">\nCAPITOLUL 11\n</div>\n\n<h1>De la strategie la acțiune</h1>\n\n<p>\nO comunitate puternică nu apare peste noapte.\nEa se construiește prin pași mici, executați consecvent.\nAcest capitol transformă strategia Becky într-un plan practic de implementare.\n</p>\n\n</div>\n\n\n\n<div class=\"section\">\n\n<h2>Roadmap-ul primelor 90 de zile</h2>\n\n<div class=\"timeline\">\n\n<div class=\"phase\">\n\n<div class=\"phase-number\">\nPrimele 30 zile\n</div>\n\n<h3>🏗 Fundamentul</h3>\n\n<p>\nConstruim infrastructura comunității.\n</p>\n\n<ul>\n\n<li>Calendar anual</li>\n\n<li>Lansarea Becky''s Friends</li>\n\n<li>Colțul Comunității</li>\n\n<li>Website</li>\n\n<li>Ritualuri recurente</li>\n\n</ul>\n\n</div>\n\n<div class=\"phase\">\n\n<div class=\"phase-number\">\nZilele 31–60\n</div>\n\n<h3>🚀 Activarea</h3>\n\n<p>\nPrimele experiențe comune.\n</p>\n\n<ul>\n\n<li>Primele evenimente recurente</li>\n\n<li>Primele fotografii pentru Copacul Becky</li>\n\n<li>Primele badge-uri</li>\n\n<li>Promovarea calendarului</li>\n\n</ul>\n\n</div>\n\n<div class=\"phase\">\n\n<div class=\"phase-number\">\nZilele 61–90\n</div>\n\n<h3>🌱 Consolidarea</h3>\n\n<p>\nFormarea nucleului comunității.\n</p>\n\n<ul>\n\n<li>Familiile „De-al Casei”</li>\n\n<li>Invită un prieten</li>\n\n<li>Familia Lunii</li>\n\n<li>Feedback și optimizare</li>\n\n</ul>\n\n</div>\n\n</div>\n\n</div>\n\n\n\n<div class=\"section\">\n\n<h2>Rolurile echipei</h2>\n\n<div class=\"roles-grid\">\n\n<div class=\"role-card\">\n\n<div class=\"emoji\">🏡</div>\n\n<h3>Gazdă</h3>\n\n<p>Primește familiile și creează atmosfera.</p>\n\n</div>\n\n<div class=\"role-card\">\n\n<div class=\"emoji\">🎯</div>\n\n<h3>Facilitator</h3>\n\n<p>Coordonează activitățile și implicarea copiilor.</p>\n\n</div>\n\n<div class=\"role-card\">\n\n<div class=\"emoji\">📸</div>\n\n<h3>Creator de conținut</h3>\n\n<p>Documentează și spune poveștile comunității.</p>\n\n</div>\n\n<div class=\"role-card\">\n\n<div class=\"emoji\">⭐</div>\n\n<h3>Becky''s Friends</h3>\n\n<p>Gestionează apartenența și relația cu membrii.</p>\n\n</div>\n\n<div class=\"role-card\">\n\n<div class=\"emoji\">❤️</div>\n\n<h3>Ambasador Becky</h3>\n\n<p>Protejează cultura și valorile comunității.</p>\n\n</div>\n\n</div>\n\n</div>\n\n\n\n<div class=\"section\">\n\n<h2>Principii de implementare</h2>\n\n<div class=\"principles\">\n\n<div class=\"principle\">\n\n<h3>🎯 Prioritatea</h3>\n\n<p>\n\nNu implementăm toate ideile simultan.\n\nConstruim mai întâi ritualuri constante și experiențe memorabile.\n\n</p>\n\n</div>\n\n<div class=\"principle\">\n\n<h3>♻ Îmbunătățire continuă</h3>\n\n<p>\n\nPlaybook-ul evoluează odată cu comunitatea.\n\nFeedback-ul real devine baza fiecărei îmbunătățiri.\n\n</p>\n\n</div>\n\n</div>\n\n</div>\n\n\n\n<div class=\"section\">\n\n<h2>Evaluare lunară</h2>\n\n<div class=\"review-grid\">\n\n<div class=\"review-item\">\n\n📈\n\n<strong>Participare</strong>\n\n</div>\n\n<div class=\"review-item\">\n\n💬\n\n<strong>Feedback</strong>\n\n</div>\n\n<div class=\"review-item\">\n\n🤝\n\n<strong>Relații create</strong>\n\n</div>\n\n<div class=\"review-item\">\n\n⭐\n\n<strong>Becky''s Friends</strong>\n\n</div>\n\n<div class=\"review-item\">\n\n💡\n\n<strong>Idei noi</strong>\n\n</div>\n\n</div>\n\n</div>\n\n\n\n<div class=\"cta\">\n\n<h2>Construim pas cu pas</h2>\n\n<p>\n\nScopul nu este perfecțiunea din prima zi, ci dezvoltarea consecventă a unei comunități care devine mai puternică în fiecare lună.\n\n</p>\n\n</div>\n\n\n\n<div class=\"section\">\n\n<h2>Ideile esențiale</h2>\n\n<div class=\"takeaways\">\n\n<div class=\"takeaway\">\n\n<div class=\"icon\">✔</div>\n\n<div>Construiește întâi fundația, apoi extinde.</div>\n\n</div>\n\n<div class=\"takeaway\">\n\n<div class=\"icon\">✔</div>\n\n<div>Consecvența este mai importantă decât complexitatea.</div>\n\n</div>\n\n<div class=\"takeaway\">\n\n<div class=\"icon\">✔</div>\n\n<div>Comunitatea se dezvoltă prin pași mici și repetabili.</div>\n\n</div>\n\n<div class=\"takeaway\">\n\n<div class=\"icon\">✔</div>\n\n<div>Feedback-ul este parte din proces.</div>\n\n</div>\n\n<div class=\"takeaway\">\n\n<div class=\"icon\">✔</div>\n\n<div>Playbook-ul evoluează odată cu Becky.</div>\n\n</div>\n\n</div>\n\n</div>\n\n</section>"},{"id":"block-013","type":"chapter","html":"<article class=\"manual-chapter\"><header class=\"manual-chapter-hero\"><div class=\"chapter-number\">CAPITOLUL 12</div><h1>Cum măsurăm succesul</h1><div class=\"manual-hero-mark\" aria-hidden=\"true\">✦</div></header><div class=\"manual-chapter-body\"><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>De ce măsurăm?</h2><div class=\"manual-section-body\"><p>Succesul unei comunități nu poate fi evaluat doar prin încasări sau numărul de vizitatori. Indicatorii trebuie să arate dacă Becky reușește să creeze relații, apartenență și experiențe memorabile.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Indicatori de participare</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>numărul familiilor participante;</li><li>rata de revenire;</li><li>participarea la evenimente recurente;</li><li>numărul familiilor noi în fiecare lună.</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Indicatori ai comunității</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>familii active în Becky Friends;</li><li>familii «De-al Casei»;</li><li>invitații realizate între membri;</li><li>familii care participă constant la ritualuri.</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>Indicatori ai experienței</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>feedback-ul părinților;</li><li>recomandările primite;</li><li>fotografiile și amintirile create;</li><li>implicarea copiilor în activități.</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Indicatori digitali</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>vizite pe website;</li><li>înscrieri la evenimente;</li><li>abonări la newsletter;</li><li>interacțiuni în social media;</li><li>vizualizarea galeriilor comunității.</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Indicatori financiari</h2><div class=\"manual-section-body\"><p>Performanța financiară rămâne importantă: rezervări, grad de ocupare, venituri recurente și costul atragerii unei familii noi. Totuși, acești indicatori sunt interpretați împreună cu cei de comunitate.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Revizuire periodică</h2><div class=\"manual-section-body\"><p>În fiecare lună și trimestru, echipa analizează datele, identifică tendințe și stabilește ce ritualuri, evenimente sau procese trebuie îmbunătățite.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>Succesul pe termen lung</h2><div class=\"manual-section-body\"><p>Cel mai valoros indicator apare atunci când familiile recomandă Becky în mod natural și aleg să revină fără a fi motivate de reduceri sau campanii.</p></div></section><section class=\"manual-conclusion\"><h2><span aria-hidden=\"true\">✦</span>Concluzie</h2><div class=\"manual-section-body\"><p>Datele sunt utile doar dacă ajută echipa să ia decizii mai bune. Scopul măsurării nu este controlul, ci înțelegerea modului în care comunitatea evoluează.</p></div></section><section class=\"manual-takeaways\"><h2><span aria-hidden=\"true\">♡</span>Idei-cheie</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>Nu măsurăm doar vizitele, ci relațiile create.</li><li>Indicatorii financiari și cei de comunitate trebuie analizați împreună.</li><li>Feedback-ul este la fel de important ca statisticile.</li><li>Deciziile se bazează pe date și observații.</li><li>Succesul înseamnă o comunitate care revine și recomandă Becky.</li></ul></div></section></div></article>"},{"id":"block-014","type":"chapter","html":"<article class=\"manual-chapter\"><header class=\"manual-chapter-hero\"><div class=\"chapter-number\">CAPITOLUL 13</div><h1>Viziunea pe termen lung</h1><div class=\"manual-hero-mark\" aria-hidden=\"true\">♡</div></header><div class=\"manual-chapter-body\"><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Dincolo de un loc de joacă</h2><div class=\"manual-section-body\"><p>Becky nu își propune doar să fie un spațiu unde copiii se joacă. Ambiția este de a deveni un reper al comunității locale, un loc asociat cu prietenii, încredere și amintiri pentru generații întregi de familii.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>O comunitate care crește organic</h2><div class=\"manual-section-body\"><p>Pe măsură ce cultura și tradițiile se consolidează, comunitatea începe să se dezvolte prin recomandări naturale. Familiile noi sunt atrase de experiențele împărtășite de cele existente, iar relațiile devin principalul motor al creșterii.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Becky peste cinci ani</h2><div class=\"manual-section-body\"><p>Imaginea dorită:</p><ul class=\"manual-list\"><li>familii care își dau întâlnire fără o invitație oficială;</li><li>copii care cresc împreună;</li><li>ritualuri recunoscute de întreaga comunitate;</li><li>un calendar așteptat cu entuziasm în fiecare an.</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">→</span>Impact asupra orașului</h2><div class=\"manual-section-body\"><p>Becky poate deveni un exemplu de bună practică pentru modul în care un spațiu privat contribuie la viața comunității. Nu doar oferă servicii, ci creează conexiuni între oameni.</p></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">✦</span>Dezvoltarea conceptului</h2><div class=\"manual-section-body\"><p>Pe termen lung pot apărea:</p><ul class=\"manual-list\"><li>programe dedicate adolescenților;</li><li>colaborări cu școli și organizații locale;</li><li>proiecte caritabile inițiate împreună cu familiile;</li><li>ediții speciale ale ritualurilor anuale.</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">♡</span>Principii care nu se schimbă</h2><div class=\"manual-section-body\"><p>Indiferent cât crește Becky, câteva valori rămân constante:</p><ul class=\"manual-list\"><li>oamenii înaintea profitului;</li><li>apartenența înaintea tranzacției;</li><li>relațiile înaintea evenimentelor;</li><li>consecvența înaintea noutății.</li></ul></div></section><section class=\"manual-section\"><h2><span aria-hidden=\"true\">◌</span>Moștenirea Becky</h2><div class=\"manual-section-body\"><p>Succesul adevărat nu va fi măsurat doar în cifre, ci în numărul familiilor care vor spune peste ani că Becky a făcut parte din copilăria lor și din povestea familiei lor.</p></div></section><section class=\"manual-conclusion\"><h2><span aria-hidden=\"true\">✦</span>Concluzie</h2><div class=\"manual-section-body\"><p>Acest playbook nu este finalul unui proiect, ci începutul unei comunități. El oferă direcția, însă adevărata valoare va fi construită în fiecare conversație, fiecare eveniment și fiecare relație creată la Becky.</p></div></section><section class=\"manual-takeaways\"><h2><span aria-hidden=\"true\">♡</span>Idei-cheie</h2><div class=\"manual-section-body\"><ul class=\"manual-list\"><li>Viziunea depășește conceptul unui loc de joacă.</li><li>Comunitatea este cel mai important activ Becky.</li><li>Creșterea trebuie să păstreze cultura și valorile.</li><li>Moștenirea se construiește prin oameni și amintiri.</li><li>Scopul final: un loc despre care oamenii spun cu naturalețe «Ne vedem la Becky.»</li></ul></div></section></div></article>"},{"id":"block-015","type":"appendix","html":"<article class=\"manual-chapter manual-appendix manual-manifest\">\n  <header class=\"manual-chapter-hero\">\n    <div class=\"chapter-number\">ANEXĂ · MANIFEST</div>\n    <h1>Manifestul Becky</h1>\n    <p class=\"manual-lead\">O declarație despre felul în care Becky transformă joaca în explorare, conectare și creștere.</p>\n    <div class=\"manual-hero-mark\" aria-hidden=\"true\">♡</div>\n  </header>\n  <section class=\"manual-section manual-manifest-identity\">\n    <div class=\"manual-section-body\">\n      <p class=\"manual-manifest-statement\"><strong>Becky este locul unde familiile găsesc activități de conectare cu sine și cu cei dragi.</strong></p>\n      <p>Aici, joaca nu este doar distracție.</p>\n      <p>Este o formă de explorare, conectare și creștere.</p>\n    </div>\n  </section>\n  <section class=\"manual-section\">\n    <h2><span aria-hidden=\"true\">✦</span>În ce credem</h2>\n    <div class=\"manual-manifesto-lines\">\n      <p><span>01</span>Credem că joaca este una dintre cele mai naturale forme prin care oamenii explorează, învață și se conectează.</p>\n      <p><span>02</span>Credem că experiențele cu sens apropie oamenii mai mult decât orice conversație.</p>\n      <p><span>03</span>Credem că fiecare familie merită un loc în care curiozitatea este încurajată, colaborarea apare firesc, iar timpul petrecut împreună lasă amintiri și îi apropie.</p>\n      <p><span>04</span>Credem că dezvoltarea nu trebuie separată de distracție. Cele mai valoroase lecții se nasc atunci când nici nu simți că înveți.</p>\n      <p><span>05</span>Credem că adulții au nevoie să redescopere joaca la fel de mult cum copiii au nevoie să o trăiască.</p>\n      <p><span>06</span>Credem că un loc prinde viață atunci când oamenii nu vin doar să participe, ci aleg să contribuie la ceea ce construim împreună.</p>\n      <p><span>07</span>Și credem că, atunci când oamenii spun firesc „Ne vedem la Becky.”, înseamnă că Becky nu mai este doar un spațiu. A devenit o parte din povestea lor.</p>\n    </div>\n  </section>\n  <section class=\"manual-section\">\n    <h2><span aria-hidden=\"true\">◌</span>Viziunea Becky</h2>\n    <div class=\"manual-section-body\">\n      <p>Transformăm aceste valori în experiențe care invită familiile să descopere, să încerce, să colaboreze și să se apropie.</p>\n      <p>Fiecare activitate Becky trebuie să aibă un sens dincolo de ocuparea timpului: să deschidă o conversație, să exerseze o abilitate, să provoace curiozitatea sau să creeze un moment de bucurie împărtășită.</p>\n      <p>Grădina, activitățile, Becky Lab, evenimentele și ghizii nu sunt idei separate. Sunt expresii ale aceleiași filozofii: <strong>joacă cu sens, conexiune autentică, dezvoltare naturală.</strong></p>\n    </div>\n  </section>\n  <section class=\"manual-section\">\n    <h2><span aria-hidden=\"true\">→</span>Ecosistemul Becky</h2>\n    <div class=\"manual-section-body\">\n      <ul class=\"manual-list\">\n        <li><strong>Spațiul</strong> deschide curiozitatea și face explorarea posibilă.</li>\n        <li><strong>Activitățile</strong> transformă joaca în experiențe de conectare și creștere.</li>\n        <li><strong>Becky Lab</strong> testează, observă și rafinează ideile care merită păstrate.</li>\n        <li><strong>Evenimentele</strong> orchestrează experiențe validate în momente memorabile.</li>\n        <li><strong>Comunitatea</strong> apare ca rezultat firesc al oamenilor care revin, contribuie și aleg să construiască împreună.</li>\n      </ul>\n    </div>\n  </section>\n  <div class=\"manual-manifesto-signoff\"><span>Joacă cu sens.</span><span>Explorare și curiozitate.</span><span>Conexiune autentică.</span><span>Dezvoltare naturală.</span></div>\n</article>"}],"updatedAt":"2026-08-04T09:11:00.414Z"}'::jsonb),
  ('styles', '{"css":":root{\n    --primary:#168F9F;\n    --primary-light:#F6EDDD;\n    --border:#B4DBDE;\n    --text:#243447;\n    --muted:#74869E;\n    --radius:20px;\n    --shadow:0 14px 35px rgba(22,143,159,.15);\n}\n\n.manual-content{\n    font-family:''Nunito'',sans-serif;\n    color:var(--text);\n    line-height:1.7;\n}\n\n.manual-content h1,\n.manual-content h2,\n.manual-content h3{\n    font-family:''Mali'',sans-serif;\n    font-weight:500;\n    letter-spacing:0;\n}\n\n.manual-content .accent,\n.manual-content em{\n    font-family:''Nunito'',sans-serif;\n    color:#F14D5D;\n}\n\n\n\n.hero{\n    margin-bottom:70px;\n}\n\n.chapter-number{\n    color:#FB7176;\n    font-size:.85rem;\n    font-weight:700;\n    letter-spacing:2px;\n    text-transform:uppercase;\n    margin-bottom:14px;\n}\n\n.manual-content .hero h1,\n.manual-content > h1{\n    font-family:''Mali'',''Nunito'',sans-serif;\n    font-weight:700;\n    color:#168F9F;\n    letter-spacing:normal;\n    -webkit-text-stroke:5px #fffdfa;\n    paint-order:stroke fill;\n    line-height:1.04;\n    text-shadow:0 2px 0 #B4DBDE, 0 5px 12px rgba(36,52,71,.08);\n}\n\n.hero h1{\n    font-size:3.1rem;\n    line-height:1.1;\n    color:var(--primary);\n    margin:0 0 24px;\n}\n\n.hero p{\n    max-width:720px;\n    font-size:1.15rem;\n    color:#526377;\n}\n\n.section{\n    margin:90px 0;\n}\n\n.section h2{\n    color:var(--primary);\n    font-size:2rem;\n    margin-bottom:35px;\n}\n\n.summary-grid{\n    display:grid;\n    grid-template-columns:repeat(4,1fr);\n    gap:22px;\n}\n\n.summary-card{\n\n    background:white;\n    border:1px solid var(--border);\n    border-radius:20px;\n    padding:28px;\n    transition:.25s;\n}\n\n.summary-card:hover{\n\n    transform:translateY(-6px);\n    box-shadow:var(--shadow);\n}\n\n.summary-card h3{\n\n    margin:0 0 14px;\n    color:var(--primary);\n    font-size:1.2rem;\n}\n\n.flow{\n    display:flex;\n    justify-content:center;\n    align-items:center;\n    gap:18px;\n    flex-wrap:wrap;\n}\n\n.flow-step{\n\n    flex:1;\n    min-width:180px;\n\n    background:var(--primary-light);\n\n    border-radius:18px;\n\n    padding:26px;\n\n    text-align:center;\n\n    border:1px solid var(--border);\n}\n\n.flow-step strong{\n\n    display:block;\n    font-size:1.05rem;\n    color:var(--primary);\n\n    margin-bottom:8px;\n}\n\n.arrow{\n\n    font-size:34px;\n    color:#CCBCD9;\n}\n\n.website-grid{\n\n    display:grid;\n\n    grid-template-columns:repeat(2,1fr);\n\n    gap:24px;\n}\n\n.website-card{\n\n    background:white;\n\n    border:1px solid var(--border);\n\n    border-radius:22px;\n\n    padding:30px;\n\n    min-height:180px;\n\n    transition:.25s;\n}\n\n.website-card:hover{\n\n    transform:translateY(-5px);\n\n    box-shadow:var(--shadow);\n}\n\n.website-card h3{\n\n    margin:0 0 18px;\n\n    color:var(--primary);\n\n    font-size:1.45rem;\n}\n\n.website-card p{\n\n    margin:0;\n\n    color:#607084;\n}\n\n.cta{\n\n    background:\n    radial-gradient(\n        circle at 50% 20%,\n        rgba(255,255,255,.95) 0%,\n        rgba(255,255,255,0) 45%\n    ),\n    linear-gradient(\n        180deg,\n        #FFF7EA 0%,\n        #F8F9F2 30%,\n        #EEF7F7 65%,\n        #DCEFF3 100%\n    );\n\n    border:1px solid var(--border);\n\n    border-radius:26px;\n\n    padding:55px;\n\n    text-align:center;\n\n    margin:90px 0;\nline-height: 1;\n}\n\n.cta h2{\n\n    margin:0;\n\n    font-size:2.4rem;\n\n    color:var(--primary);\n}\n\n.cta p{\n\n    margin:18px auto 34px;\n\n    max-width:650px;\n\n    color:#607084;\n}\n\n.cta-btn{\n\n    display:inline-flex;\n\n    align-items:center;\n\n    justify-content:center;\n\n    padding:18px 34px;\n\n    border-radius:14px;\n\n    background:var(--primary);\n\n    color:white;\n\n    font-weight:700;\n\n    letter-spacing:.3px;\n}\n\n.kpi-grid{\n\n    display:grid;\n\n    grid-template-columns:repeat(4,1fr);\n\n    gap:22px;\n}\n\n.kpi{\n\n    background:white;\n\n    border:1px solid var(--border);\n\n    border-radius:22px;\n\n    padding:32px;\n\n    min-height:170px;\n\n    display:flex;\n\n    flex-direction:column;\n\n    justify-content:center;\n}\n\n.kpi small{\n\n    text-transform:uppercase;\n\n    letter-spacing:2px;\n\n    font-size:.72rem;\n\n    color:#9AA9BA;\n\n    margin-bottom:8px;\n}\n\n.kpi strong{\n\n    font-size:2rem;\n\n    line-height:1;\n\n    color:var(--primary);\n\n    margin-bottom:14px;\n}\n\n.kpi p{\n\n    margin:0;\n\n    color:#6B7D92;\n\n    font-size:.95rem;\n}\n\n.takeaways{\n\n    display:grid;\n\n    gap:16px;\n\n    margin-top:30px;\n}\n\n.takeaway{\n\n    display:flex;\n\n    align-items:flex-start;\n\n    gap:16px;\n\n    background:#F6EDDD;\n\n    border-radius:16px;\n\n    padding:18px 22px;\n}\n\n.takeaway .icon{\n\n    color:#2F9B4D;\n\n    font-weight:700;\n}\n\n/* Safety + responsive layout for the manual preview and exported document. */\n.manual-content,\n.manual-content *{\n    box-sizing:border-box;\n}\n\n.manual-content{\n    width:100%;\n    max-width:100%;\n    min-width:0;\n    overflow-wrap:anywhere;\n}\n\n.manual-content img,\n.manual-content video,\n.manual-content iframe,\n.manual-content svg{\n    display:block;\n    max-width:100%;\n    height:auto;\n}\n\n.manual-content .summary-grid,\n.manual-content .kpi-grid{\n    grid-template-columns:repeat(auto-fit,minmax(min(100%,220px),1fr));\n}\n\n.manual-content .website-grid{\n    grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));\n}\n\n.manual-content .flow{\n    width:100%;\n    max-width:100%;\n}\n\n.manual-content .flow-step{\n    min-width:0;\n    flex:1 1 180px;\n}\n\n.manual-content .hero h1,\n.manual-content h1,\n.manual-content h2,\n.manual-content h3,\n.manual-content p{\n    max-width:100%;\n    overflow-wrap:anywhere;\n}\n\n@media (max-width:700px){\n    .manual-content .summary-grid,\n    .manual-content .kpi-grid,\n    .manual-content .website-grid{\n        grid-template-columns:1fr;\n    }\n\n    .manual-content .cta{\n        padding:28px 20px;\n    }\n\n    .manual-content .hero h1{\n        font-size:2.2rem;\n    }\n}\n\n/* Ritm comun pentru capitolele strategice: elimină golurile verticale accidentale\n   dintre hero, secțiuni și CTA, păstrând spațiul intern al componentelor. */\n.manual-content .chapter > .hero{\n    margin-bottom:42px;\n}\n\n.manual-content .chapter > .section{\n    margin:52px 0;\n}\n\n.manual-content .chapter > .hero + .section{\n    margin-top:0;\n}\n\n.manual-content .chapter > .section + .section{\n    margin-top:54px;\n}\n\n.manual-content .chapter > .section h2{\n    margin-bottom:24px;\n}\n\n.manual-content .chapter > .cta{\n    margin:54px 0;\n}\n\n/* Capitolul 10 — aceeași energie vizuală ca pagina publică Becky Friends. */\n.manual-content .chapter-website{\n    position:relative;\n    isolation:isolate;\n    overflow:hidden;\n    padding:48px clamp(24px,5vw,72px) 58px;\n    border:1px solid rgba(180,219,222,.9);\n    border-radius:30px;\n    background:linear-gradient(145deg,#fffdfa 0%,#fffdfa 56%,#F3FAF9 100%);\n    box-shadow:0 18px 46px rgba(35,52,72,.08);\n}\n\n.manual-content .chapter-website:before{\n    content:\"\";\n    position:absolute;\n    z-index:-1;\n    width:280px;\n    height:280px;\n    top:-125px;\n    right:-75px;\n    background:url(''/assets/cloud.png'') center/contain no-repeat;\n    opacity:.16;\n    filter:drop-shadow(0 10px 12px rgba(35,52,72,.08));\n}\n\n.manual-content .chapter-website .hero{\n    margin-bottom:38px;\n    padding:4px 0 34px;\n    border-bottom:1px solid rgba(180,219,222,.65);\n}\n\n.manual-content .chapter-website .hero h1{\n    max-width:900px;\n    color:#198E9F;\n    font-size:clamp(42px,5.8vw,76px);\n}\n\n.manual-content .chapter-website .hero p{\n    max-width:760px;\n    margin:22px 0 0;\n    color:#52677D;\n    font-size:18px;\n    line-height:1.55;\n}\n\n.manual-content .chapter-website .section{\n    position:relative;\n    margin:44px 0;\n}\n\n.manual-content .chapter-website .section h2{\n    margin:0 0 22px;\n    color:#198E9F;\n    font-size:clamp(28px,3.5vw,44px);\n    line-height:1.08;\n}\n\n.manual-content .chapter-website .section h2:after{\n    content:\"\";\n    display:block;\n    width:180px;\n    height:17px;\n    margin-top:12px;\n    background:url(''/assets/teal_line_separator.png'') left center/contain no-repeat;\n    opacity:.72;\n}\n\n.manual-content .chapter-website .summary-grid,\n.manual-content .chapter-website .website-grid,\n.manual-content .chapter-website .kpi-grid{\n    gap:18px;\n}\n\n.manual-content .chapter-website .summary-card,\n.manual-content .chapter-website .website-card,\n.manual-content .chapter-website .kpi{\n    position:relative;\n    overflow:hidden;\n    border:1px solid rgba(180,219,222,.65);\n    border-radius:22px;\n    background:#fffdfa;\n    box-shadow:0 10px 25px rgba(35,52,72,.06);\n    transition:transform .28s ease,box-shadow .28s ease,filter .28s ease;\n}\n\n.manual-content .chapter-website .summary-card:after,\n.manual-content .chapter-website .website-card:after,\n.manual-content .chapter-website .kpi:after{\n    content:\"\";\n    position:absolute;\n    inset:0;\n    pointer-events:none;\n    background:linear-gradient(112deg,transparent 24%,rgba(255,255,255,.5) 46%,rgba(255,255,255,.08) 54%,transparent 70%);\n    transform:translateX(-120%);\n    transition:transform .75s cubic-bezier(.2,.7,.2,1);\n}\n\n.manual-content .chapter-website .summary-card:hover,\n.manual-content .chapter-website .website-card:hover,\n.manual-content .chapter-website .kpi:hover{\n    transform:translateY(-5px);\n    filter:brightness(1.025) saturate(1.04);\n    box-shadow:0 18px 35px rgba(35,52,72,.13);\n}\n\n.manual-content .chapter-website .summary-card:hover:after,\n.manual-content .chapter-website .website-card:hover:after,\n.manual-content .chapter-website .kpi:hover:after{\n    transform:translateX(120%);\n}\n\n.manual-content .chapter-website .summary-card h3,\n.manual-content .chapter-website .website-card h3{\n    position:relative;\n    z-index:1;\n    color:#198E9F;\n}\n\n.manual-content .chapter-website .website-card:nth-child(2):before,\n.manual-content .chapter-website .website-card:nth-child(3):before{\n    content:\"\";\n    position:absolute;\n    right:-25px;\n    bottom:-38px;\n    width:190px;\n    height:190px;\n    background:center/contain no-repeat;\n    opacity:.15;\n    pointer-events:none;\n}\n\n.manual-content .chapter-website .website-card:nth-child(2):before{background-image:url(''/assets/carduri/Petreceri.png'')}\n.manual-content .chapter-website .website-card:nth-child(3):before{background-image:url(''/assets/carduri/Evenimente.png'')}\n.manual-content .chapter-website .website-card p{position:relative;z-index:1}\n\n.manual-content .chapter-website .flow-step{\n    background:linear-gradient(145deg,#EFF9F8,#DDF2F3);\n    border-color:rgba(51,169,186,.25);\n    box-shadow:0 8px 20px rgba(51,169,186,.07);\n}\n\n.manual-content .chapter-website .flow-step:nth-of-type(3){\n    background:linear-gradient(145deg,#FFF8EF,#FDE8DA);\n    border-color:rgba(246,178,139,.35);\n}\n\n.manual-content .chapter-website .kpi small{color:#198E9F}\n.manual-content .chapter-website .kpi strong{font-family:''Mali'',sans-serif;color:#198E9F}\n.manual-content .chapter-website .takeaways{gap:12px;margin-top:22px}\n.manual-content .chapter-website .takeaway{background:rgba(246,237,221,.6);border:1px solid rgba(253,203,75,.18)}\n\n@media(max-width:700px){\n    .manual-content .chapter-website{padding:32px 20px 40px;border-radius:22px}\n    .manual-content .chapter-website .hero h1{font-size:42px}\n    .manual-content .chapter-website .hero p{font-size:16px}\n}\n\n/* Editorial system shared by the complete playbook. */\n.manual-content{\n    --manual-paper:#fffdfa;\n    --manual-ink:#233448;\n    --manual-muted:#62778f;\n    --manual-teal:#198e9f;\n    --manual-coral:#fb7176;\n    --manual-yellow:#fdcb4b;\n    --manual-line:rgba(180,219,222,.72);\n}\n\n.manual-content > .manual-chapter,\n.manual-content > .manual-overview,\n.manual-content > .chapter:not(.chapter-website){\n    position:relative;\n    isolation:isolate;\n    width:100%;\n    margin:0 auto 54px;\n    padding:clamp(30px,5vw,68px);\n    overflow:hidden;\n    border:1px solid var(--manual-line);\n    border-radius:30px;\n    background:linear-gradient(145deg,#fffdfa 0%,#fffdfa 70%,#f4faf9 100%);\n    box-shadow:0 20px 52px rgba(35,52,72,.09);\n}\n\n.manual-content > .manual-chapter:before,\n.manual-content > .manual-overview:before,\n.manual-content > .chapter:not(.chapter-website):before{\n    content:\"\";\n    position:absolute;\n    z-index:-1;\n    top:-95px;\n    right:-85px;\n    width:260px;\n    height:260px;\n    border-radius:50%;\n    background:radial-gradient(circle,rgba(180,219,222,.35),rgba(180,219,222,0) 70%);\n}\n\n.manual-content .manual-chapter-hero,\n.manual-content .manual-cover{\n    position:relative;\n    min-height:230px;\n    margin:0 0 34px;\n    padding:4px clamp(72px,10vw,145px) 38px 0;\n    border-bottom:1px solid var(--manual-line);\n}\n\n.manual-content .manual-chapter-hero h1,\n.manual-content .manual-cover h1{\n    max-width:850px;\n    margin:0;\n    color:var(--manual-teal);\n    font:600 clamp(38px,5.5vw,68px)/1.06 ''Mali'',sans-serif;\n    letter-spacing:-.025em;\n    text-wrap:balance;\n}\n\n.manual-content .manual-chapter-hero .chapter-number,\n.manual-content .manual-cover .chapter-number{\n    margin-bottom:16px;\n    color:var(--manual-coral);\n    font-size:12px;\n    font-weight:900;\n    letter-spacing:.16em;\n}\n\n.manual-content .manual-hero-mark{\n    position:absolute;\n    top:22px;\n    right:16px;\n    display:grid;\n    width:82px;\n    height:82px;\n    place-items:center;\n    border:1px solid rgba(251,113,118,.18);\n    border-radius:50%;\n    background:linear-gradient(145deg,#fff4ef,#fbe0e6);\n    color:var(--manual-coral);\n    font:500 37px/1 ''Mali'',sans-serif;\n    box-shadow:0 12px 26px rgba(251,113,118,.12);\n}\n\n.manual-content .manual-lead,\n.manual-content .manual-cover > p{\n    max-width:780px;\n    margin:22px 0 0;\n    color:var(--manual-muted);\n    font-size:17px;\n    line-height:1.65;\n}\n\n.manual-content .manual-chapter-body{\n    display:grid;\n    gap:18px;\n}\n\n.manual-content .manual-section,\n.manual-content .manual-conclusion,\n.manual-content .manual-takeaways{\n    position:relative;\n    margin:0;\n    padding:clamp(22px,3vw,32px);\n    border:1px solid rgba(180,219,222,.55);\n    border-radius:22px;\n    background:rgba(255,255,255,.68);\n    box-shadow:0 8px 22px rgba(35,52,72,.045);\n}\n\n.manual-content .manual-section h2,\n.manual-content .manual-conclusion h2,\n.manual-content .manual-takeaways h2{\n    display:flex;\n    align-items:center;\n    gap:11px;\n    margin:0 0 16px;\n    color:var(--manual-teal);\n    font:600 clamp(20px,2.4vw,28px)/1.2 ''Mali'',sans-serif;\n    letter-spacing:-.01em;\n}\n\n.manual-content .manual-section h2 > span,\n.manual-content .manual-conclusion h2 > span,\n.manual-content .manual-takeaways h2 > span{\n    display:grid;\n    flex:0 0 30px;\n    width:30px;\n    height:30px;\n    place-items:center;\n    border-radius:50%;\n    background:#edf8f7;\n    color:var(--manual-coral);\n    font:700 14px/1 ''Nunito'',sans-serif;\n}\n\n.manual-content .manual-section-body > p{\n    max-width:880px;\n    margin:0 0 12px;\n    color:var(--manual-muted);\n    font-size:15.5px;\n    line-height:1.72;\n}\n\n.manual-content .manual-section-body > p:last-child{margin-bottom:0}\n.manual-content .manual-manifest-statement{max-width:900px;font:700 clamp(22px,3vw,34px)/1.25 ''Mali'',sans-serif;color:#8d70a3!important}\n.manual-content .manual-manifest > .manual-section{margin-bottom:18px}\n.manual-content .manual-manifest > .manual-section:last-of-type{margin-bottom:0}\nbody .topbar h1,\nbody .panel-heading h2,\nbody .editor-toolbar h2,\nbody .empty-state h3,\nbody .css-heading h2,\nbody .manual-content h1,\nbody .manual-content h2,\nbody .manual-content h3{\n    font-family:''Mali'',sans-serif!important;\n}\nbody .manual-content .manual-cover h1,\nbody .manual-content .manual-chapter-hero h1{\n    font-size:clamp(34px,4vw,54px)!important;\n    line-height:1.08!important;\n}\n\n.manual-content .manual-list{\n    display:grid;\n    grid-template-columns:repeat(2,minmax(0,1fr));\n    gap:10px;\n    margin:8px 0 0;\n    padding:0;\n    list-style:none;\n}\n\n.manual-content .manual-list li{\n    position:relative;\n    min-height:52px;\n    padding:14px 15px 14px 42px;\n    border:1px solid rgba(180,219,222,.48);\n    border-radius:15px;\n    background:#fffdfa;\n    color:#52677d;\n    font-size:14px;\n    line-height:1.45;\n}\n\n.manual-content .manual-list li:before{\n    content:\"✓\";\n    position:absolute;\n    top:14px;\n    left:15px;\n    display:grid;\n    width:19px;\n    height:19px;\n    place-items:center;\n    border-radius:50%;\n    background:#ddf2f3;\n    color:var(--manual-teal);\n    font-size:11px;\n    font-weight:900;\n}\n\n.manual-content .manual-quote{\n    margin:15px 0;\n    padding:18px 22px;\n    border-left:4px solid var(--manual-coral);\n    border-radius:0 16px 16px 0;\n    background:#fff2ee;\n    color:#354b61;\n    font:600 17px/1.55 ''Mali'',sans-serif;\n}\n\n.manual-content .manual-flowline{\n    margin:14px 0;\n    padding:18px;\n    border:1px dashed rgba(25,142,159,.35);\n    border-radius:16px;\n    background:#edf8f7;\n    color:var(--manual-teal);\n    font-weight:900;\n    line-height:1.7;\n    text-align:center;\n}\n\n.manual-content .manual-conclusion{\n    border-color:rgba(25,142,159,.28);\n    background:linear-gradient(135deg,#edf8f7,#ddf2f3);\n}\n\n.manual-content .manual-conclusion h2{color:#147b88}\n\n.manual-content .manual-takeaways{\n    border-color:rgba(253,203,75,.35);\n    background:linear-gradient(135deg,#fffaf0,#fff1c9);\n}\n\n.manual-content .manual-takeaways h2{color:#b98408}\n.manual-content .manual-takeaways .manual-list li{border-color:rgba(253,203,75,.32);background:rgba(255,253,250,.84)}\n.manual-content .manual-takeaways .manual-list li:before{background:#fdcb4b;color:#6c5410}\n\n.manual-content .manual-strategy{\n    border-color:rgba(251,113,118,.42);\n    background:linear-gradient(145deg,#fffdfa 0%,#fff7f2 56%,#fbe9eb 100%);\n}\n\n.manual-content .manual-strategy:after{\n    content:\"\";\n    position:absolute;\n    top:0;\n    bottom:0;\n    left:0;\n    width:8px;\n    background:linear-gradient(#fb7176,#fdcb4b,#40a5a8);\n}\n\n.manual-content .manual-strategy .manual-chapter-hero h1{color:#233448}\n.manual-content .manual-strategy-grid{grid-template-columns:minmax(0,1fr);align-items:start}\n.manual-content .manual-strategy .manual-list{grid-template-columns:minmax(0,1fr)}\n.manual-content .manual-strategy-grid .manual-section:nth-last-child(-n+3){grid-column:1/-1}\n\n.manual-content .manual-cover{\n    min-height:300px;\n    padding-top:18px;\n}\n\n.manual-content .manual-cover h1{max-width:760px;font-size:clamp(45px,7vw,82px)}\n\n.manual-content .manual-cover-note{\n    display:flex;\n    width:max-content;\n    max-width:100%;\n    margin-top:28px;\n    padding:12px 17px;\n    flex-wrap:wrap;\n    gap:6px 10px;\n    border:1px solid rgba(251,113,118,.2);\n    border-radius:999px;\n    background:#fff2ee;\n    color:#52677d;\n    font-size:13px;\n}\n\n.manual-content .manual-cover-note strong{color:var(--manual-coral)}\n\n.manual-content .manual-overview-grid{\n    display:grid;\n    grid-template-columns:repeat(2,minmax(0,1fr));\n    gap:13px;\n}\n\n.manual-content .manual-overview-card{\n    display:block;\n    padding:19px;\n    border:1px solid rgba(180,219,222,.58);\n    border-radius:18px;\n    background:rgba(255,255,255,.72);\n}\n\n.manual-content .manual-overview-card h2{\n    display:flex;\n    align-items:baseline;\n    gap:8px;\n    margin:0 0 8px;\n    color:#233448;\n    font:700 16px/1.3 ''Nunito'',sans-serif;\n}\n\n.manual-content .manual-overview-number{\n    flex:0 0 24px;\n    color:var(--manual-coral);\n    font-size:12px;\n    font-weight:900;\n    letter-spacing:.06em;\n}\n\n.manual-content .manual-overview-separator{\n    color:#b4a99e;\n    font-weight:500;\n}\n\n.manual-content .manual-overview-card p{\n    margin:0 0 0 40px;\n    color:#71849a;\n    font-size:12.5px;\n    line-height:1.5;\n}\n\n.manual-content .manual-appendix{\n    border-color:rgba(203,186,216,.72);\n    background:linear-gradient(145deg,#fffdfa 0%,#fcf8fd 62%,#eee5f4 100%);\n}\n\n.manual-content .manual-appendix .manual-chapter-hero h1{color:#8d70a3}\n.manual-content .manual-appendix .manual-hero-mark{border-color:rgba(203,186,216,.5);background:#eee5f4;color:#8d70a3}\n\n.manual-content .manual-manifesto-lines{\n    display:grid;\n    gap:14px;\n}\n\n.manual-content .manual-manifesto-lines p{\n    display:grid;\n    grid-template-columns:42px minmax(0,1fr);\n    gap:16px;\n    align-items:start;\n    margin:0;\n    padding:22px 24px;\n    border:1px solid rgba(203,186,216,.5);\n    border-radius:19px;\n    background:rgba(255,255,255,.76);\n    color:#354b61;\n    font:600 17px/1.55 ''Mali'',sans-serif;\n    box-shadow:0 8px 20px rgba(91,71,123,.05);\n}\n\n.manual-content .manual-manifesto-lines p > span{\n    color:#a58cb9;\n    font:900 11px/1.7 ''Nunito'',sans-serif;\n    letter-spacing:.08em;\n}\n\n.manual-content .manual-manifesto-signoff{\n    display:flex;\n    justify-content:center;\n    gap:8px;\n    margin-top:24px;\n    flex-wrap:wrap;\n}\n\n.manual-content .manual-manifesto-signoff span{\n    padding:9px 13px;\n    border-radius:999px;\n    background:#fff2ee;\n    color:#fb7176;\n    font-size:12px;\n    font-weight:900;\n}\n\n/* Bring the two previously designed chapters into the same reading frame. */\n.manual-content > .chapter:not(.chapter-website) .hero{\n    margin:0 0 34px;\n    padding-bottom:34px;\n    border-bottom:1px solid var(--manual-line);\n}\n\n.manual-content > .chapter:not(.chapter-website) .hero h1{font-size:clamp(38px,5.5vw,68px)}\n.manual-content > .chapter:not(.chapter-website) .section{margin:38px 0}\n\n@media(max-width:800px){\n    .manual-content .manual-strategy-grid,\n    .manual-content .manual-overview-grid,\n    .manual-content .manual-list{grid-template-columns:1fr}\n    .manual-content .manual-strategy-grid .manual-section:nth-last-child(-n+3){grid-column:auto}\n    .manual-content .manual-chapter-hero,\n    .manual-content .manual-cover{padding-right:0;padding-top:100px}\n    .manual-content .manual-hero-mark{top:0;right:auto;left:0;width:68px;height:68px}\n}\n\n@media(max-width:560px){\n    .manual-content > .manual-chapter,\n    .manual-content > .manual-overview,\n    .manual-content > .chapter:not(.chapter-website){padding:24px 18px;border-radius:22px}\n    .manual-content .manual-chapter-hero h1,\n    .manual-content .manual-cover h1{font-size:36px}\n    .manual-content .manual-section,\n    .manual-content .manual-conclusion,\n    .manual-content .manual-takeaways{padding:19px 16px}\n    .manual-content .manual-overview-card{padding:15px}\n    .manual-content .manual-overview-card p{margin-left:0}\n    .manual-content .manual-manifesto-lines p{grid-template-columns:30px minmax(0,1fr);padding:18px 16px;font-size:15px}\n}\n\n@media print{\n    .manual-content > .manual-chapter,\n    .manual-content > .manual-overview,\n    .manual-content > .chapter{break-after:page;box-shadow:none}\n    .manual-content .manual-section,\n    .manual-content .manual-conclusion,\n    .manual-content .manual-takeaways{break-inside:avoid}\n}\n"}'::jsonb),
  ('workspaces', '{"updatedAt":null,"workspaces":[{"id":"parties","label":"Dashboard Petreceri","eyebrow":"WORKSPACE / PETRECERI","description":"Organizează, urmărește și dezvoltă experiențele de petrecere Becky.","items":[{"id":"party-overview","icon":"✦","name":"Privire de ansamblu","description":"Rezumatul petrecerilor și al rezervărilor."},{"id":"party-calendar","icon":"◌","name":"Calendar petreceri","description":"Toate petrecerile planificate într-un singur loc."},{"id":"party-packages","icon":"♡","name":"Pachete și experiențe","description":"Tipuri de petreceri, opțiuni și beneficii."},{"id":"party-followup","icon":"✧","name":"Follow-up familii","description":"Pașii de după petrecere și invitația de revenire."}]},{"id":"events","label":"Dashboard Evenimente","eyebrow":"WORKSPACE / EVENIMENTE","description":"Construiește calendarul de ritualuri și întâlniri ale comunității.","items":[{"id":"event-calendar","icon":"✦","name":"Calendar comunitate","description":"Evenimente recurente și momente speciale."},{"id":"event-rituals","icon":"◌","name":"Ritualuri Becky","description":"Formatele care aduc familiile împreună."},{"id":"event-planning","icon":"♡","name":"Planificare eveniment","description":"Obiectiv, echipă, resurse și pași de execuție."},{"id":"event-memory","icon":"✧","name":"Memoria evenimentelor","description":"Fotografii, povești și concluzii după fiecare întâlnire."}]},{"id":"parents","label":"Meniu Activități Părinți","eyebrow":"WORKSPACE / PĂRINȚI","description":"Un spațiu pentru activități, conversații și conexiuni între părinți.","items":[{"id":"parent-meetups","icon":"♡","name":"Întâlniri de comunitate","description":"Momente relaxate pentru părinți și familii."},{"id":"parent-coffee","icon":"✦","name":"Coffee & S Play","description":"Dimineți cu conversații și joacă pentru cei mici."},{"id":"parent-workshops","icon":"◌","name":"Ateliere pentru părinți","description":"Idei, resurse și invitați pentru viața de familie."},{"id":"parent-network","i